messages.text:
docs: expect exit 1 from the smoke check of a file with no smoke test

@ID-CONFIG-10 expected exit 2 when smoke.every_file rejects a feature file with live scenarios and
no smoke test. That is a policy failure, which exits 1 by PLAN §7 and by tests smoke check's help;
2 is a usage or config error. The scenario was written wrong, as @ID-CONFIG-07 was.

version: 1
ledger: { files: "gone/phase-{group}.yaml", id: "T-\\d+" }
commits:
  types: [chore, docs]
  footers:
    Task: { source: ledger, required_for: [chore], validate_for: all, read_at: commit }

version: 1
commits:
  header_lint: { stdin: "sh lint.sh" }

version: 1
commits:
  header_lint: { stdin: "cat >/dev/null; echo 'lint: no config found'; exit 9" }

version: 1
ledger: { files: "tasks/phase-{group}.yaml", group: { pattern: "\\d+", numeric: true }, id: "T-\\d+" }
commits:
  types: [feat, fix, chore, docs]
  header_lint: { use: builtin }
  footers:
    Task: { source: ledger, required_for: [chore], validate_for: all, read_at: commit }

version: 1
commits:
  header_lint: { use: builtin }

version: 1
commits:
  header_lint: { use: builtin, stdin: "echo delegated; exit 1" }

version: 1
commits:
  header_lint: { use: command, stdin: "cat >/dev/null; echo '✖   delegated [local-rule]'; exit 1" }

version: 1
commits:
  footers:
    Fixture: { source: { tests: fixture }, validate_for: [feat], read_at: commit }
    Also: { source: { tests: fixture }, validate_for: [feat], read_at: commit }
tests:
